from pathlib import Path
from hashlib import sha256
root=Path(__file__).resolve().parents[1]
problems=[('Which model should we use?','Benchmark frontier, open-weight, and specialized models on the actual task.'),('How do we know it works?','Build evaluations from historical cases, expert judgment, known failure modes, and business requirements.'),('Should we fine-tune?','Test whether prompting, retrieval, fine-tuning, distillation, or another architecture actually improves performance.'),('How should an agent act?','Define tools, permissions, state, recovery, escalation, and task-level success criteria.'),('How do we control cost and latency?','Measure quality against inference cost and latency, then route work to the appropriate model or system.'),('What happens after deployment?','Use production failures and human corrections to expand evaluations and improve the system.')]
caps=[('Evaluation & benchmarking','Build representative evaluation datasets, automated and human graders, and regression tests. Compare systems against task-level performance and known failure modes.','DATASETS / GRADERS / REGRESSION'),('Agentic systems','Build agents that use tools, maintain state, operate within defined permissions, recover from failures, and escalate when required.','TOOLS / STATE / RECOVERY'),('Model specialization','Evaluate fine-tuning and distillation against prompting and retrieval. Specialize models when task-specific data can materially improve quality, latency, or cost.','FINE-TUNING / DISTILLATION'),('Retrieval & knowledge systems','Build retrieval over proprietary documents and structured data. Measure both whether the right information is retrieved and whether the model uses it correctly.','RETRIEVAL / EVIDENCE / CONTEXT'),('Model selection & routing','Benchmark frontier, open-weight, and specialized models. Route tasks based on complexity, confidence, latency, cost, and risk.','BENCHMARK / ROUTE / ESCALATE'),('Production ML systems','Build the tracing, monitoring, versioning, deployment, and rollback infrastructure needed to operate and improve AI systems in production.','TRACES / DEPLOYMENT / FEEDBACK')]
steps=[('Define','Understand the workflow, data, failure modes, constraints, and success criteria.'),('Measure','Build a representative evaluation set and establish a baseline.'),('Architect','Test the simplest system that can meet the requirements.'),('Build','Integrate the system with real data, tools, and workflows.'),('Improve','Use production traces, corrections, and failures to measure regressions and improve performance.')]
principles=[('Evals before optimization.','If we cannot measure the task, we cannot reliably improve it.'),('Use the simplest system that works.','The right answer may be a frontier model, a specialized smaller model, retrieval, deterministic software, or a combination.'),('Optimize the complete system.','Quality, reliability, latency, cost, security, maintainability, and operational risk all matter.'),('Learn from production.','Failures and human corrections should become evaluation cases, regression tests, and training data where appropriate.')]
mail='mailto:contact@dremli.com?subject=Discuss%20an%20AI%20problem'
